// Film 68 "The AI Race Will Be Decided by 2027" · shared kit (lead). Base: f10_editorial (palette P, easing, du/person, halo, glowText,
// finish) + f67_kit (goldText, goldSpan, paperCard, dataCard, quoteCard, clipPlate, headline fit, edgeSafe, source).
// Plan: docs/MOTION.md · shots: docs/shots.md (generated by tools/shots68.mjs from scenes/plan.mjs).
//
// Colour code (meaning, never broken): AMERICA = muted steel blue (US) · CHINA = muted terracotta (CN, never crisis red) · EUROPE = pale
// lilac (EU, a lane without a runner) · the AI / the third lane = cyan light (AI) · GOLD = the scoreboard light, numbers, what holds ·
// the yellow coat = only you. The AI is never a robot: it is a cyan disc of light with rings (channel rule). Humanoid robots appear only
// as the literal robots of the Beijing sprint (R4).
// Rules: no canvas/pattern cache per frame; seeded randomness only; nothing from nowhere (every shot grows out of the baton's landing point).
import { Path2D } from '@napi-rs/canvas';
import * as E from './f10_editorial.mjs';
import * as K from './f67_kit.mjs';
export * from './f67_kit.mjs';
const { W, H, P, rgba, mixHex, clamp, lerp, span, smooth, sineIO, expoOut, expoIn, halo, rad, lin, prng, drift } = E;
export const { stars, dust, rays } = E;
export const rise = K.rise;
export const TAU = Math.PI * 2;

export const US = { body: '#7f9fd8', line: '#a9c2ee', deep: '#2c4a86', text: '#c6d8f6' };
export const CN = { body: '#d9805f', line: '#f0a98a', deep: '#7a3626', text: '#f6c9b4' };
export const EU = { body: '#b9b4d6', line: '#d6d2ea', deep: '#4c4870', text: '#dcd8ee' };
export const AI = { core: '#e9fbff', body: '#8fe6ff', line: '#bff2ff', deep: '#0a6f8c', halo: '#5fd0f2', text: '#c9f4ff' };
export const GOLD = K.GOLD, PAPER = K.PAPER, CREAM = P.cream, MUTED = '#a49fc4';
export const SIDE = { US, CN, EU, AI };

// ---------------------------------------------------------------------------------------------------------------- background + camera
// every shot: deep night gradient, a soft glow where the hero sits, slow stars. o: { gx, gy (glow centre), gcol, ga, stars, top, bot }
export function bg(ctx, t, o = {}) {
  ctx.save(); ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.fillStyle = lin(ctx, 0, 0, 0, H, [[0, o.top ?? P.night0], [.6, o.mid ?? P.night1], [1, o.bot ?? P.ind0]]); ctx.fillRect(0, 0, W, H);
  const gx = o.gx ?? W * .5, gy = o.gy ?? H * .45;
  ctx.fillStyle = rad(ctx, gx, gy, o.gr ?? 900, [[0, rgba(o.gcol ?? P.blue0, o.ga ?? .35)], [1, rgba(P.night0, 0)]]); ctx.fillRect(0, 0, W, H);
  if (o.stars !== 0) stars(ctx, o.seed ?? 3, o.stars ?? 90, t, [drift(t * .3, 20, 1) - 20, -10, W + 40, H * .75], .5);
  ctx.restore();
}
// a slow motivated camera inside a shot: push from z0 to z1 about (fx, fy) over [a, b], plus drift. Call after bg, inside save/restore.
export function shotCam(ctx, t, S, o = {}) {
  const u = sineIO(span(t, S.a, S.b)), z = lerp(o.z0 ?? 1, o.z1 ?? 1.04, u), fx = o.fx ?? W / 2, fy = o.fy ?? H / 2;
  ctx.translate(fx + (o.dx ?? 0) * u + drift(t, 4, S.seed ?? 1), fy + (o.dy ?? 0) * u + drift(t, 3, (S.seed ?? 1) + 5)); ctx.scale(z, z); ctx.translate(-fx, -fy);
}

// ---------------------------------------------------------------------------------------------------------------- type
// caps label (Inter 600, spaced), rises behind its baseline
export function cap(ctx, s, x, y, u, o = {}) {
  u = clamp(u); if (u <= 0) return 0;
  const size = o.size ?? 28;
  K.maskLine(ctx, [[s, 0]], x, y, size, u, { serif: false, weight: o.weight ?? 600, col: o.col ?? CREAM, glow: o.glow ?? false, align: o.align });
  return K.measure(s, size, false, o.weight ?? 600);
}
// serif line (Instrument Serif)
export function serif(ctx, s, x, y, size, u, o = {}) {
  u = clamp(u); if (u <= 0) return 0;
  K.maskLine(ctx, [[s, 0]], x, y, size, u, { serif: true, col: o.col ?? CREAM, glow: o.glow ?? true, align: o.align });
  return K.measure(s, size, true);
}
// big gold number / word
export function big(ctx, s, x, y, size, u, o = {}) {
  u = clamp(u); if (u <= 0) return;
  K.goldText(ctx, [[s, o.gold ?? 1]], x, y, size, u, { serif: o.serif ?? true, align: o.align ?? 'center', weight: o.weight, col: o.col });
}
// a number counting up: fmt(v) → string
export function counter(ctx, t, x, y, size, v0, v1, u, fmt, o = {}) {
  if (u <= 0) return; const v = lerp(v0, v1, expoOut(clamp(u)));
  E.glowText(ctx, fmt(v), x, y, { size, serif: o.serif ?? true, align: o.align ?? 'center', col: o.col ?? GOLD.text, glow: o.glow ?? true, a: clamp(u * 4) });
}
export const src = (ctx, t, t0, t1, s, o) => K.source(ctx, t, t0, t1, s, o);

// ---------------------------------------------------------------------------------------------------------------- marks of light
// horizontal bar of light, grows from x with u. col = a SIDE palette ({body, line, deep}). o: { th, a, value, vsize, label, lsize }
export function bar(ctx, x, y, len, u, col, o = {}) {
  const k = expoOut(clamp(u)), L = Math.max(0, len * k), th = o.th ?? 34, a = o.a ?? 1; if (a <= 0 || u <= 0) return;
  ctx.save(); ctx.globalAlpha *= a;
  if (L > 2) {
    halo(ctx, x + L, y, th * 2.2, .22 * (o.glow ?? 1), col.line, col.line);
    ctx.fillStyle = lin(ctx, 0, y - th / 2, 0, y + th / 2, [[0, mixHex(col.line, '#ffffff', .15)], [.45, col.body], [1, col.deep]]);
    ctx.beginPath(); ctx.roundRect(x, y - th / 2, L, th, [3, th * .3, th * .3, 3]); ctx.fill();
    ctx.fillStyle = rgba('#ffffff', .18); ctx.fillRect(x, y - th / 2, L, 2);
  }
  ctx.restore();
  if (o.label) cap(ctx, o.label, x - 24, y + (o.lsize ?? 26) * .36, rise(span(u, 0, .5)) * a, { size: o.lsize ?? 26, align: 'right', col: col.text ?? CREAM });
  if (o.value) E.glowText(ctx, o.value, x + L + 22, y + (o.vsize ?? 40) * .34, { size: o.vsize ?? 40, serif: true, col: CREAM, glow: false, a: a * rise(span(u, .55, 1)) });
}
// vertical column of light, grows up from base y
export function column(ctx, x, base, w, hgt, u, col, o = {}) {
  const k = expoOut(clamp(u)), L = hgt * k, a = o.a ?? 1; if (u <= 0 || a <= 0) return;
  ctx.save(); ctx.globalAlpha *= a;
  halo(ctx, x + w / 2, base - L, w * 1.2, .2, col.line, col.line);
  ctx.fillStyle = lin(ctx, x, 0, x + w, 0, [[0, col.deep], [.5, col.body], [1, mixHex(col.line, '#fff', .1)]]);
  ctx.beginPath(); ctx.roundRect(x, base - L, w, L, [w * .18, w * .18, 2, 2]); ctx.fill();
  ctx.restore();
  if (o.value) E.glowText(ctx, o.value, x + w / 2, base - L - 22, { size: o.vsize ?? 44, serif: true, align: 'center', col: CREAM, glow: false, a: a * rise(span(u, .5, 1)) });
  if (o.label) cap(ctx, o.label, x + w / 2, base + 44, rise(span(u, 0, .5)) * a, { size: o.lsize ?? 26, align: 'center', col: col.text ?? CREAM });
}
// a line of light along pts (polyline), u = drawn share; col palette
export function lightLine(ctx, pts, u0, u1, col, o = {}) {
  u0 = clamp(u0); u1 = clamp(u1); if (u1 <= u0 || pts.length < 2) return null;
  const len = [0]; for (let i = 1; i < pts.length; i++) len.push(len[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  const L = len[len.length - 1], at = (d) => { let i = 1; while (i < pts.length - 1 && len[i] < d) i++; const f = clamp((d - len[i - 1]) / Math.max(1e-6, len[i] - len[i - 1])); return [lerp(pts[i - 1][0], pts[i][0], f), lerp(pts[i - 1][1], pts[i][1], f), i]; };
  const [sx, sy, i0] = at(u0 * L), [ex, ey, i1] = at(u1 * L), sub = [[sx, sy]];
  for (let i = i0; i < i1; i++) sub.push(pts[i]); sub.push([ex, ey]);
  const w = o.w ?? 4, a = o.a ?? 1;
  for (const [k, al, c, op] of [[4, .16, col.line, 'lighter'], [1.8, .9, col.body, 'source-over'], [.7, 1, mixHex(col.line, '#ffffff', .4), 'source-over']]) {
    ctx.save(); ctx.globalCompositeOperation = op; ctx.strokeStyle = c; ctx.globalAlpha *= al * a; ctx.lineWidth = w * k; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    if (o.dash) ctx.setLineDash(o.dash.map((d) => d * w));
    ctx.beginPath(); sub.forEach((p, i) => (i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]))); ctx.stroke(); ctx.restore();
  }
  if (o.head && u1 < 1) halo(ctx, ex, ey, w * 9, .5 * a, col.line, '#ffffff');
  if (o.arrow && u1 > .98) { const [px, py] = pts[pts.length - 2], ang = Math.atan2(ey - py, ex - px), s = w * 4.5;
    ctx.save(); ctx.globalAlpha *= a; ctx.fillStyle = col.line; ctx.beginPath(); ctx.moveTo(ex + Math.cos(ang) * s * .4, ey + Math.sin(ang) * s * .4); ctx.lineTo(ex + Math.cos(ang + 2.5) * s, ey + Math.sin(ang + 2.5) * s); ctx.lineTo(ex + Math.cos(ang - 2.5) * s, ey + Math.sin(ang - 2.5) * s); ctx.closePath(); ctx.fill(); ctx.restore(); }
  return [ex, ey];
}
export const curvePts = (f, x0, x1, n = 80) => { const r = []; for (let i = 0; i <= n; i++) { const x = lerp(x0, x1, i / n); r.push([x, f(x)]); } return r; };
// a donut share: frac of a ring filled (from 12 o'clock), u grows it
export function donut(ctx, x, y, r, frac, u, col, o = {}) {
  if (u <= 0) return; const th = o.th ?? r * .28, a = o.a ?? 1;
  ctx.save(); ctx.globalAlpha *= a * clamp(u * 3); ctx.lineCap = 'butt';
  ctx.strokeStyle = rgba(P.blue1, .55); ctx.lineWidth = th; ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.stroke();
  const e = frac * expoOut(clamp(u));
  ctx.strokeStyle = col.body; ctx.lineWidth = th; ctx.beginPath(); ctx.arc(x, y, r, -Math.PI / 2, -Math.PI / 2 + TAU * e); ctx.stroke();
  ctx.globalCompositeOperation = 'lighter'; ctx.strokeStyle = rgba(col.line, .35); ctx.lineWidth = th * .3; ctx.beginPath(); ctx.arc(x, y, r + th * .2, -Math.PI / 2, -Math.PI / 2 + TAU * e); ctx.stroke();
  ctx.restore();
  if (o.value) E.glowText(ctx, o.value, x, y + (o.vsize ?? 64) * .34, { size: o.vsize ?? 64, serif: true, align: 'center', col: CREAM, glow: false, a: a * rise(span(u, .4, 1)) });
  if (o.label) cap(ctx, o.label, x, y + r + th + 52, rise(span(u, .2, .8)) * a, { size: o.lsize ?? 26, align: 'center', col: col.text ?? CREAM });
}
// a grid of dots: n dots in cols; colOf(k) → palette or null (dim); u reveals in reading order
export function dots(ctx, t, x, y, n, cols, gap, r, u, colOf, o = {}) {
  if (u <= 0) return; const a = o.a ?? 1;
  ctx.save(); ctx.globalAlpha *= a;
  for (let k = 0; k < n; k++) {
    const e = rise(span(u, k / n * .7, k / n * .7 + .3)); if (e <= 0) continue;
    const c = colOf(k), cx = x + (k % cols) * gap, cy = y + Math.floor(k / cols) * gap;
    ctx.fillStyle = c ? c.body : rgba(P.blue1, .5); ctx.beginPath(); ctx.arc(cx, cy, r * (.5 + .5 * e), 0, TAU); ctx.fill();
  }
  ctx.restore();
}

// ---------------------------------------------------------------------------------------------------------------- the AI: a disc of light
// cyan disc with rings that pulse inwards when it "thinks". never a robot, never a brain. o: { a, rings, pulse, dark (0..1 unlit) }
export function orb(ctx, t, x, y, r, o = {}) {
  const a = o.a ?? 1; if (a <= 0 || r <= 0) return;
  const dark = clamp(o.dark ?? 0), lit = 1 - dark;
  ctx.save(); ctx.globalAlpha *= a;
  if (lit > 0) halo(ctx, x, y, r * 3.2, .35 * lit, AI.halo, AI.core);
  ctx.fillStyle = rad(ctx, x - r * .25, y - r * .3, r * 1.1, [[0, mixHex(mixHex(AI.core, AI.body, .2), P.night1, dark * .85)], [.55, mixHex(AI.body, P.night1, dark * .8)], [1, mixHex(AI.deep, P.night0, dark * .7)]]);
  ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
  const n = o.rings ?? 3;
  for (let i = 0; i < n; i++) {
    const ph = ((t * (o.pulse ?? .35) + i / n) % 1), rr = r * (1.9 - ph * .85);
    ctx.strokeStyle = rgba(AI.line, (.5 * Math.sin(Math.PI * ph)) * (.25 + .75 * lit)); ctx.lineWidth = Math.max(1.2, r * .035);
    ctx.beginPath(); ctx.arc(x, y, rr, 0, TAU); ctx.stroke();
  }
  ctx.restore();
}

// ---------------------------------------------------------------------------------------------------------------- runners
// a sprinter silhouette with volume (tapered capsules), side view, facing right. ph = stride phase (rad). o: { col palette, robot, a, lean }
export function runner(ctx, x, y, h, ph, o = {}) {
  const col = o.col ?? US, a = o.a ?? 1; if (a <= 0) return;
  const s = Math.sin(ph), c = Math.cos(ph), lean = o.lean ?? .16, robot = !!o.robot;
  ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.scale(h, h);
  ctx.fillStyle = rgba(P.night0, .45); ctx.beginPath(); ctx.ellipse(0, 0, .22, .022, 0, 0, TAU); ctx.fill();
  const hip = [0, -.5 - .025 * Math.abs(c)], sh = [hip[0] + Math.sin(lean) * .33, hip[1] - Math.cos(lean) * .33];
  const limb = (p0, ang1, l1, ang2, l2, w0, w1, colr) => {
    const k = [p0[0] + Math.sin(ang1) * l1, p0[1] + Math.cos(ang1) * l1], e = [k[0] + Math.sin(ang2) * l2, k[1] + Math.cos(ang2) * l2];
    ctx.strokeStyle = colr; ctx.lineCap = robot ? 'square' : 'round'; ctx.lineJoin = 'round';
    ctx.lineWidth = w0; ctx.beginPath(); ctx.moveTo(...p0); ctx.lineTo(...k); ctx.stroke();
    ctx.lineWidth = w1; ctx.beginPath(); ctx.moveTo(...k); ctx.lineTo(...e); ctx.stroke();
    return e;
  };
  const far = mixHex(col.deep, P.night0, .35), near = col.body;
  const leg = (q, w0, w1, colr) => { const th = .8 * Math.sin(q), sh2 = th - (.25 + 1.3 * Math.max(0, -Math.cos(q)) * (Math.sin(q) < .3 ? 1 : .4)); return limb(hip, th, .27, sh2, .27, w0, w1, colr); };
  const arm = (q, w0, w1, colr) => { const ua = -.85 * Math.sin(q), fa = ua + 1.45; return limb(sh, ua, .16, fa, .15, w0, w1, colr); };
  leg(ph + Math.PI, .12, .09, far); arm(ph + Math.PI, .085, .07, far);
  // torso
  ctx.strokeStyle = near; ctx.lineCap = robot ? 'square' : 'round'; ctx.lineWidth = robot ? .17 : .16; ctx.beginPath(); ctx.moveTo(...hip); ctx.lineTo(...sh); ctx.stroke();
  // head
  const hd = [sh[0] + Math.sin(lean) * .1 + .01, sh[1] - .11];
  ctx.fillStyle = near; ctx.beginPath(); if (robot) ctx.roundRect(hd[0] - .055, hd[1] - .06, .11, .11, .025); else ctx.arc(hd[0], hd[1], .075, 0, TAU); ctx.fill();
  leg(ph, .125, .095, near); arm(ph, .09, .075, near);
  if (robot) { ctx.fillStyle = rgba(AI.line, .8); ctx.fillRect(hd[0] + .01, hd[1] - .015, .04, .02); }
  else { ctx.strokeStyle = rgba(col.line, .5); ctx.lineWidth = .012; ctx.beginPath(); ctx.moveTo(hip[0] + .05, hip[1]); ctx.lineTo(sh[0] + .05, sh[1]); ctx.stroke(); }
  ctx.restore();
}

// ---------------------------------------------------------------------------------------------------------------- the track (flat, from the side-above)
// lanes: [{ col, label }] top → bottom. o: { x0, x1, y0, pitch, u (lanes draw from left), finish (x of the finish line, 0..1 reveal), a }
export function track(ctx, t, o) {
  const { x0 = 160, x1 = 1760, y0 = 380, pitch = 150, lanes = [] } = o, u = clamp(o.u ?? 1), a = o.a ?? 1; if (u <= 0 || a <= 0) return;
  ctx.save(); ctx.globalAlpha *= a;
  const xe = lerp(x0, x1, expoOut(u));
  ctx.fillStyle = rgba(mixHex(P.ind0, '#3a2a40', .25), .55); ctx.fillRect(x0, y0 - pitch / 2, xe - x0, pitch * lanes.length);
  for (let i = 0; i <= lanes.length; i++) { const y = y0 - pitch / 2 + i * pitch; ctx.strokeStyle = rgba(CREAM, .28); ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(x0, y); ctx.lineTo(xe, y); ctx.stroke(); }
  lanes.forEach((ln, i) => {
    const y = y0 + i * pitch, la = ln.a ?? 1;
    if (ln.glow) { ctx.save(); ctx.globalAlpha *= ln.glow; ctx.fillStyle = lin(ctx, x0, 0, xe, 0, [[0, rgba(ln.col.body, .05)], [1, rgba(ln.col.body, .28)]]); ctx.fillRect(x0, y - pitch / 2 + 2, xe - x0, pitch - 4); ctx.restore(); }
    if (ln.label) cap(ctx, ln.label, x0 - 28, y + 10, rise(span(u, .1 + i * .1, .6 + i * .1)) * la, { size: ln.lsize ?? 26, align: 'right', col: ln.col.text });
  });
  if (o.finish != null && o.finish > 0) {
    const fx = lerp(x0, x1, o.fx ?? .9), fu = expoOut(clamp(o.finish));
    for (let k = 0; k < lanes.length * 6; k++) { const yy = y0 - pitch / 2 + k * pitch / 6; if (k / (lanes.length * 6) > fu) break; ctx.fillStyle = k % 2 ? rgba(CREAM, .85) : rgba(P.night0, .8); ctx.fillRect(fx - 6, yy, 12, pitch / 6); }
  }
  ctx.restore();
}

// ---------------------------------------------------------------------------------------------------------------- objects
export function chip(ctx, t, x, y, s, o = {}) {
  const a = o.a ?? 1; if (a <= 0 || s <= 0) return;
  const col = o.col ?? GOLD;
  ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.rotate(o.rot ?? 0);
  if (o.glow !== false) halo(ctx, 0, 0, s * 1.4, .25, col.halo ?? col.line, col.core ?? '#fff');
  ctx.strokeStyle = col.line ?? col.body; ctx.lineWidth = s * .035; ctx.lineCap = 'round';
  for (let k = 0; k < 5; k++) { const v = -s * .3 + k * s * .15; for (const [x1, y1, x2, y2] of [[v, -s * .5, v, -s * .66], [v, s * .5, v, s * .66], [-s * .5, v, -s * .66, v], [s * .5, v, s * .66, v]]) { ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); } }
  ctx.fillStyle = lin(ctx, 0, -s / 2, 0, s / 2, [[0, mixHex(col.body, '#fff', .15)], [1, col.deep ?? col.mid]]); ctx.beginPath(); ctx.roundRect(-s / 2, -s / 2, s, s, s * .08); ctx.fill();
  ctx.fillStyle = rgba(P.night0, .55); ctx.beginPath(); ctx.roundRect(-s * .3, -s * .3, s * .6, s * .6, s * .05); ctx.fill();
  ctx.strokeStyle = rgba(col.line ?? CREAM, .5); ctx.lineWidth = s * .015; ctx.strokeRect(-s * .22, -s * .22, s * .44, s * .44);
  ctx.restore();
}
// a lightning stroke of power (gold), from p0 to p1, u drawn
export function bolt(ctx, x, y, s, u, o = {}) {
  if (u <= 0) return; const pts = [[x - s * .1, y - s * .5], [x - s * .32, y + s * .06], [x - s * .02, y + s * .02], [x - s * .18, y + s * .5], [x + s * .3, y - s * .12], [x + s * .02, y - s * .08], [x + s * .2, y - s * .5]];
  ctx.save(); ctx.globalAlpha *= (o.a ?? 1) * clamp(u * 2); halo(ctx, x, y, s * 1.3, .3 * clamp(u), GOLD.halo, GOLD.core);
  ctx.fillStyle = lin(ctx, 0, y - s / 2, 0, y + s / 2, [[0, GOLD.hot], [1, GOLD.mid]]); ctx.beginPath(); pts.forEach((p, i) => (i ? ctx.lineTo(...p) : ctx.moveTo(...p))); ctx.closePath();
  ctx.save(); ctx.clip(); ctx.fillRect(x - s, y + s / 2 - s * expoOut(clamp(u)), s * 2, s * 1.2); ctx.restore(); ctx.restore();
}
// a small file/model card (a model's weights): x,y centre, s width
export function modelCard(ctx, t, x, y, s, o = {}) {
  const a = o.a ?? 1; if (a <= 0) return; const col = o.col ?? US, h = s * 1.25;
  ctx.save(); ctx.globalAlpha *= a; ctx.translate(x, y); ctx.rotate(o.rot ?? 0);
  ctx.fillStyle = rgba(P.night0, .4); ctx.beginPath(); ctx.roundRect(-s / 2 + 5, -h / 2 + 8, s, h, s * .06); ctx.fill();
  ctx.fillStyle = lin(ctx, 0, -h / 2, 0, h / 2, [[0, mixHex(P.ind2, col.body, .35)], [1, mixHex(P.night1, col.deep, .5)]]); ctx.beginPath(); ctx.roundRect(-s / 2, -h / 2, s, h, s * .06); ctx.fill();
  ctx.strokeStyle = rgba(col.line, .8); ctx.lineWidth = 2; ctx.stroke();
  for (let k = 0; k < 6; k++) { ctx.fillStyle = rgba(col.line, .45); ctx.fillRect(-s * .34, -h * .28 + k * h * .1, s * (k % 3 === 2 ? .4 : .68), 3); }
  if (o.label) E.glowText(ctx, o.label, 0, h / 2 - s * .1, { size: Math.max(16, s * .13), weight: 600, align: 'center', col: col.text, glow: false, spacing: .1 });
  ctx.restore();
}
// a document card from paperCard with lines; returns box
export const doc = (ctx, t, x, y, w, h, o) => K.paperCard(ctx, t, x, y, w, h, o);

// the baton: a gold point of light with a short trail (the carrier between shots)
export function baton(ctx, x, y, u, o = {}) {
  const r = o.r ?? 9, col = o.col ?? GOLD;
  halo(ctx, x, y, r * 7, .65 * (o.a ?? 1), col.halo ?? col.line, col.core ?? '#fff');
  ctx.save(); ctx.globalAlpha *= o.a ?? 1; ctx.fillStyle = col.core ?? '#fff'; ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill(); ctx.restore();
}
// a seed of light that a shot's first element grows from (draw it while u < 1)
export function seed(ctx, x, y, u, o = {}) { const k = 1 - clamp(u); if (k <= 0) return; baton(ctx, x, y, 0, { a: k, r: (o.r ?? 9) * (1 + u * .5), col: o.col }); }

// ---------------------------------------------------------------------------------------------------------------- flags (muted, flat)
export function flag(ctx, side, x, y, w, u = 1, o = {}) {
  if (u <= 0) return; const h = w * .62, k = expoOut(clamp(u));
  ctx.save(); ctx.globalAlpha *= (o.a ?? 1) * clamp(u * 3); ctx.beginPath(); ctx.rect(x, y, w * k, h); ctx.clip();
  if (side === 'US') {
    for (let i = 0; i < 7; i++) { ctx.fillStyle = i % 2 ? mixHex(CREAM, P.blue2, .25) : mixHex('#b4524a', P.night1, .3); ctx.fillRect(x, y + i * h / 7, w, h / 7 + .5); }
    ctx.fillStyle = mixHex(US.deep, P.night1, .2); ctx.fillRect(x, y, w * .42, h * 4 / 7);
    ctx.fillStyle = rgba(CREAM, .8); for (let r = 0; r < 4; r++) for (let c = 0; c < 5; c++) { ctx.beginPath(); ctx.arc(x + w * .05 + c * w * .08, y + h * .08 + r * h * .13, w * .011, 0, TAU); ctx.fill(); }
  } else if (side === 'CN') {
    ctx.fillStyle = mixHex('#c4432f', P.night1, .22); ctx.fillRect(x, y, w, h);
    const star = (cx, cy, r) => { ctx.beginPath(); for (let i = 0; i < 10; i++) { const rr = i % 2 ? r * .42 : r, a = -Math.PI / 2 + i * Math.PI / 5; ctx.lineTo(cx + Math.cos(a) * rr, cy + Math.sin(a) * rr); } ctx.closePath(); ctx.fill(); };
    ctx.fillStyle = mixHex('#f2c84b', P.night1, .1); star(x + w * .17, y + h * .27, w * .1); for (const [px, py] of [[.33, .1], [.4, .2], [.4, .34], [.33, .44]]) star(x + w * px, y + h * py, w * .033);
  }
  ctx.restore();
}

// ---------------------------------------------------------------------------------------------------------------- THE SCORECARD (explainer device)
// flat board, top centre: AMERICA  n : m  CHINA; rows of rounds with a dot that flies to the winner's side.
// o: { x, y, w, u, us, cn (scores, may be fractional while counting), rows: [{ label, win: 'US'|'CN'|null, u }], third (0..1 the dark third lane row) }
export function scorecard(ctx, t, o) {
  const u = clamp(o.u ?? 1); if (u <= 0) return; const x = o.x ?? 410, y = o.y ?? 150, w = o.w ?? 1100, rows = o.rows ?? [], rh = o.rh ?? 84;
  const h = 210 + rows.length * rh + (o.third ? rh : 0), k = expoOut(u);
  ctx.save(); ctx.globalAlpha *= (o.a ?? 1) * clamp(u * 2.5);
  ctx.translate(x + w / 2, y + h / 2); ctx.scale(lerp(.92, 1, k), lerp(.92, 1, k)); ctx.translate(-w / 2, -h / 2);
  halo(ctx, w / 2, 110, w * .7, .12, GOLD.halo, GOLD.core);
  ctx.fillStyle = lin(ctx, 0, 0, 0, h, [[0, mixHex(P.ind1, P.night1, .3)], [1, P.night1]]); ctx.beginPath(); ctx.roundRect(0, 0, w, h, 16); ctx.fill();
  ctx.strokeStyle = rgba(GOLD.line, .55); ctx.lineWidth = 2.5; ctx.stroke();
  cap(ctx, 'AMERICA', w * .2, 70, rise(span(u, .1, .6)), { size: 34, align: 'center', col: US.text });
  cap(ctx, 'CHINA', w * .8, 70, rise(span(u, .1, .6)), { size: 34, align: 'center', col: CN.text });
  ctx.fillStyle = US.body; ctx.fillRect(w * .2 - 60, 86, 120, 5); ctx.fillStyle = CN.body; ctx.fillRect(w * .8 - 60, 86, 120, 5);
  const sc = (v) => String(Math.round(v ?? 0));
  if (o.us != null) {
  E.glowText(ctx, `${sc(o.us)}`, w * .41, 170, { size: 140, weight: 600, align: 'center', col: GOLD.text });
  E.glowText(ctx, ':', w * .5, 160, { size: 110, weight: 600, align: 'center', col: GOLD.text });
  E.glowText(ctx, `${sc(o.cn)}`, w * .59, 170, { size: 140, weight: 600, align: 'center', col: GOLD.text });
  } else if (o.head) cap(ctx, o.head, w / 2, 150, rise(span(u, .2, .8)), { size: 30, align: 'center', col: GOLD.text });
  if (o.flash) halo(ctx, o.flash.side === 'US' ? w * .41 : w * .59, 120, 160, .5 * o.flash.a, GOLD.halo, GOLD.core);
  rows.forEach((r, i) => {
    const ru = clamp(r.u ?? 1); if (ru <= 0) return; const yy = 230 + i * rh;
    ctx.strokeStyle = rgba(CREAM, .12); ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(30, yy - rh * .5); ctx.lineTo(w - 30, yy - rh * .5); ctx.stroke();
    cap(ctx, r.label, w / 2, yy + 11, rise(ru), { size: 30, align: 'center', col: r.hi ? GOLD.text : CREAM });
    if (r.win) { const wu = clamp(r.wu ?? 1), tx = r.win === 'US' ? w * .1 : w * .9, px = lerp(w / 2, tx, sineIO(wu)), col = r.win === 'US' ? US : CN;
      if (wu > 0) { halo(ctx, px, yy, 40, .4, col.line, '#fff'); ctx.fillStyle = col.body; ctx.beginPath(); ctx.arc(px, yy, 16, 0, TAU); ctx.fill(); } }
  });
  if (o.third) {
    const yy = 230 + rows.length * rh, lit = clamp(o.thirdLit ?? 0);
    ctx.fillStyle = rgba(mixHex(P.night0, AI.deep, lit * .6), .8); ctx.beginPath(); ctx.roundRect(30, yy - rh * .42, w - 60, rh * .84, 10); ctx.fill();
    if (lit > 0) halo(ctx, w / 2, yy, w * .4, .3 * lit, AI.halo, AI.core);
    cap(ctx, o.thirdLabel ?? 'THIRD LANE', w / 2, yy + 10, clamp(o.third), { size: 24, align: 'center', col: mixHex(MUTED, AI.text, lit) });
  }
  ctx.restore();
}

// ---------------------------------------------------------------------------------------------------------------- icons (flat light shapes)
export function icon(ctx, kind, x, y, s, u = 1, o = {}) {
  if (u <= 0) return; const k = expoOut(clamp(u)), col = o.col ?? { body: CREAM, line: CREAM, deep: P.blue1 };
  ctx.save(); ctx.globalAlpha *= (o.a ?? 1) * clamp(u * 2.5); ctx.translate(x, y); ctx.scale(lerp(.7, 1, k), lerp(.7, 1, k));
  ctx.fillStyle = lin(ctx, 0, -s / 2, 0, s / 2, [[0, mixHex(col.body, '#fff', .1)], [1, mixHex(col.body, col.deep, .5)]]); ctx.strokeStyle = col.line; ctx.lineWidth = s * .04;
  if (kind === 'phone') { ctx.beginPath(); ctx.roundRect(-s * .3, -s * .5, s * .6, s, s * .08); ctx.fill(); ctx.fillStyle = rgba(P.night0, .6); ctx.beginPath(); ctx.roundRect(-s * .24, -s * .4, s * .48, s * .76, s * .04); ctx.fill(); }
  else if (kind === 'bank') { ctx.beginPath(); ctx.moveTo(-s * .55, -s * .2); ctx.lineTo(0, -s * .52); ctx.lineTo(s * .55, -s * .2); ctx.closePath(); ctx.fill(); for (let i = 0; i < 4; i++) ctx.fillRect(-s * .42 + i * s * .26, -s * .12, s * .1, s * .5); ctx.fillRect(-s * .55, s * .4, s * 1.1, s * .1); }
  else if (kind === 'hospital') { ctx.beginPath(); ctx.roundRect(-s * .45, -s * .45, s * .9, s * .9, s * .06); ctx.fill(); ctx.fillStyle = rgba(P.night0, .55); ctx.fillRect(-s * .08, -s * .3, s * .16, s * .6); ctx.fillRect(-s * .3, -s * .08, s * .6, s * .16); }
  else if (kind === 'factory') { ctx.beginPath(); ctx.moveTo(-s * .55, s * .45); ctx.lineTo(-s * .55, -s * .05); ctx.lineTo(-s * .25, -s * .25); ctx.lineTo(-s * .25, -s * .05); ctx.lineTo(s * .05, -s * .25); ctx.lineTo(s * .05, -s * .05); ctx.lineTo(s * .3, -s * .25); ctx.lineTo(s * .3, -s * .55); ctx.lineTo(s * .48, -s * .55); ctx.lineTo(s * .48, s * .45); ctx.closePath(); ctx.fill(); }
  else if (kind === 'datacenter') { for (let i = 0; i < 3; i++) { ctx.fillRect(-s * .45, -s * .45 + i * s * .32, s * .9, s * .26); ctx.fillStyle = rgba(AI.line, .8); for (let j = 0; j < 5; j++) ctx.fillRect(-s * .35 + j * s * .12, -s * .36 + i * s * .32, s * .05, s * .06); ctx.fillStyle = lin(ctx, 0, -s / 2, 0, s / 2, [[0, col.body], [1, mixHex(col.body, col.deep, .5)]]); } }
  else if (kind === 'house') { ctx.beginPath(); ctx.moveTo(-s * .45, s * .45); ctx.lineTo(-s * .45, -s * .05); ctx.lineTo(0, -s * .45); ctx.lineTo(s * .45, -s * .05); ctx.lineTo(s * .45, s * .45); ctx.closePath(); ctx.fill(); ctx.fillStyle = rgba(GOLD.hot, .9); ctx.fillRect(-s * .12, s * .05, s * .24, s * .2); }
  else if (kind === 'laptop') { ctx.beginPath(); ctx.roundRect(-s * .4, -s * .35, s * .8, s * .52, s * .04); ctx.fill(); ctx.fillRect(-s * .52, s * .2, s * 1.04, s * .08); ctx.fillStyle = rgba(P.night0, .55); ctx.fillRect(-s * .33, -s * .28, s * .66, s * .38); }
  else if (kind === 'globe') { ctx.beginPath(); ctx.arc(0, 0, s * .45, 0, TAU); ctx.fill(); ctx.strokeStyle = rgba(P.night0, .5); ctx.lineWidth = s * .03; ctx.beginPath(); ctx.ellipse(0, 0, s * .2, s * .45, 0, 0, TAU); ctx.stroke(); ctx.beginPath(); ctx.moveTo(-s * .45, 0); ctx.lineTo(s * .45, 0); ctx.stroke(); }
  else if (kind === 'capitol') { ctx.beginPath(); ctx.arc(0, -s * .12, s * .22, Math.PI, 0); ctx.fill(); ctx.fillRect(-s * .03, -s * .5, s * .06, s * .16); ctx.fillRect(-s * .5, -s * .1, s, s * .1); for (let i = 0; i < 5; i++) ctx.fillRect(-s * .44 + i * s * .21, 0, s * .07, s * .34); ctx.fillRect(-s * .55, s * .36, s * 1.1, s * .1); }
  else if (kind === 'gate') { ctx.beginPath(); ctx.moveTo(-s * .5, s * .5); ctx.lineTo(-s * .5, -s * .1); ctx.lineTo(-s * .36, -s * .1); ctx.lineTo(-s * .36, -s * .3); ctx.lineTo(s * .36, -s * .3); ctx.lineTo(s * .36, -s * .1); ctx.lineTo(s * .5, -s * .1); ctx.lineTo(s * .5, s * .5); ctx.lineTo(s * .2, s * .5); ctx.lineTo(s * .2, s * .05); ctx.lineTo(-s * .2, s * .05); ctx.lineTo(-s * .2, s * .5); ctx.closePath(); ctx.fill(); ctx.fillRect(-s * .56, -s * .44, s * 1.12, s * .1); }
  ctx.restore();
}
// a small person silhouette (crowds, groups) with volume
export function folk(ctx, x, y, h, o = {}) { E.person(ctx, x, y, h, { pose: o.pose, dir: o.dir, look: o.look, light: o.light ?? .6, alpha: o.a, rim: o.rim }); }

// ---------------------------------------------------------------------------------------------------------------- THE STADIUM (leitbild, thumbnail A)
// 4 anchors only: hook, 2:2, the third lane lights up, the end. o: { us, cn, title, third (0..1 visible), thirdLit, u, duX, duPose, floods }
export function stadium(ctx, t, o = {}) {
  const lit = clamp(o.floods ?? 1);
  bg(ctx, t, { gy: H * .3, ga: .25, gcol: P.blue0, stars: 140, seed: 11 });
  // stands (two tiers of dark curves with tiny windows)
  for (const [yy, col, seed] of [[640, mixHex(P.ind0, P.night1, .4), 21], [720, P.night1, 22]]) {
    ctx.fillStyle = col; ctx.beginPath(); ctx.moveTo(0, yy - 120); ctx.quadraticCurveTo(W / 2, yy - 40, W, yy - 120); ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
    const r = prng(seed); for (let k = 0; k < 70; k++) { const px = r() * W, py = yy - 100 + r() * 70 + Math.pow((px - W / 2) / W, 2) * -260; if (Math.abs(px - W / 2) < 640 && yy < 700) continue; ctx.fillStyle = rgba(GOLD.hot, (.35 + .4 * Math.sin(t * (.4 + r()) + k)) * .6); ctx.fillRect(px, py, 5, 7); }
  }
  // floodlight masts + beams
  for (const sx of [-1, 1]) {
    const mx = W / 2 + sx * 800, my = 150;
    ctx.fillStyle = P.night0; ctx.fillRect(mx - 9, my, 18, 700);
    ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.globalAlpha = .18 * lit;
    ctx.fillStyle = lin(ctx, mx, my, W / 2, H * .9, [[0, rgba(GOLD.line, .7)], [1, rgba(GOLD.line, 0)]]); ctx.beginPath(); ctx.moveTo(mx, my); ctx.lineTo(W / 2 - sx * 200, H); ctx.lineTo(W / 2 + sx * 500, H); ctx.closePath(); ctx.fill(); ctx.restore();
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) { halo(ctx, mx - 30 + i * 30, my - 30 + j * 26, 26, .5 * lit, GOLD.halo, GOLD.core); }
  }
  // the board
  const bx = 360, by = 110, bw = 1200, bh = 500;
  ctx.fillStyle = P.night0; ctx.fillRect(bx + 120, by + bh, 30, 160); ctx.fillRect(bx + bw - 150, by + bh, 30, 160);
  ctx.fillStyle = lin(ctx, 0, by, 0, by + bh, [[0, mixHex(P.ind1, P.night1, .25)], [1, mixHex(P.night1, P.ind0, .5)]]); ctx.beginPath(); ctx.roundRect(bx, by, bw, bh, 10); ctx.fill();
  ctx.strokeStyle = rgba(GOLD.line, .45); ctx.lineWidth = 3; ctx.stroke();
  halo(ctx, bx + bw / 2, by + bh * .4, bw * .55, .1, GOLD.halo, GOLD.core);
  const tu = clamp(o.u ?? 1);
  const title = o.title ?? 'AI RACE';
  ctx.save(); ctx.font = '100px "Inter Black"'; const tw = ctx.measureText(title).width / 100; ctx.restore();
  const ts = Math.min(170, 820 / (tw * .9));
  ctx.save(); ctx.translate(bx + bw / 2, by + 200); ctx.scale(.9, 1); ctx.font = `${ts}px "Inter Black"`; ctx.textAlign = 'center';
  ctx.globalAlpha *= rise(span(tu, 0, .5)); ctx.shadowColor = rgba(GOLD.halo, .7); ctx.shadowBlur = 40; ctx.fillStyle = '#fff6d8'; ctx.fillText(title, 0, 0); ctx.shadowBlur = 0; ctx.fillStyle = '#fffbea'; ctx.fillText(title, 0, 0); ctx.restore();
  const su = rise(span(tu, .3, .9));
  if (o.score !== false) {
    cap(ctx, 'USA', bx + 200, by + 330, su, { size: 64, align: 'center', weight: 600, col: '#fff6d8', glow: true });
    cap(ctx, 'CHINA', bx + bw - 200, by + 330, su, { size: 64, align: 'center', weight: 600, col: '#fff6d8', glow: true });
    flag(ctx, 'US', bx + 110, by + 360, 180, su); flag(ctx, 'CN', bx + bw - 290, by + 360, 180, su);
    const sc = o.scoreText ?? `${o.us ?? 2} : ${o.cn ?? 2}`;
    ctx.save(); ctx.globalAlpha *= su; E.glowText(ctx, sc, bx + bw / 2, by + 440, { size: 190, weight: 600, align: 'center', col: '#fff6d8' }); ctx.restore();
  }
  if (o.mid) o.mid(ctx, bx, by, bw, bh);
  // the third lane strip under the score
  if (o.third) {
    const lit3 = clamp(o.thirdLit ?? 0), yy = by + bh + 44, a3 = clamp(o.third);
    ctx.save(); ctx.globalAlpha *= a3; ctx.fillStyle = mixHex(P.night0, AI.deep, lit3 * .7); ctx.beginPath(); ctx.roundRect(bx + 60, yy - 22, bw - 120, 44, 8); ctx.fill(); ctx.strokeStyle = rgba(mixHex(MUTED, AI.line, lit3), .5); ctx.lineWidth = 2; ctx.stroke();
    if (lit3 > 0) { halo(ctx, bx + bw / 2, yy, bw * .45, .45 * lit3, AI.halo, AI.core); ctx.fillStyle = rgba(AI.line, .9 * lit3); ctx.fillRect(bx + 60, yy - 2, (bw - 120) * expoOut(lit3), 4); }
    cap(ctx, o.thirdLabel ?? '', bx + bw / 2, yy + 9, a3, { size: 22, align: 'center', col: mixHex(MUTED, AI.text, lit3) });
    ctx.restore();
  }
  // the infield + track edge, light pool where you stand
  ctx.fillStyle = mixHex(P.night0, P.ind0, .4); ctx.beginPath(); ctx.moveTo(0, 860); ctx.quadraticCurveTo(W / 2, 800, W, 860); ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath(); ctx.fill();
  const dx = o.duX ?? W / 2;
  ctx.save(); ctx.globalCompositeOperation = 'lighter'; ctx.fillStyle = rad(ctx, dx, 960, 260, [[0, rgba(GOLD.hot, .3 * lit)], [1, rgba(GOLD.hot, 0)]]); ctx.fillRect(dx - 300, 820, 600, 260); ctx.restore();
  if (o.du !== false) E.du(ctx, dx, o.duY ?? 958, o.duH ?? 150, { pose: o.duPose ?? 'look', look: o.look ?? 1 });
}

// phrase helpers for a shot: G(phrase, nth) = time of the phrase (searched from just before the shot), U(phrase, d, off) = 0..1 ramp
export function phr(T, S, t) {
  const G = (p, n = 0) => T.G(p, n, S.a - .8);
  const U = (p, d = .8, off = 0, n = 0) => clamp((t - G(p, n) - off) / d);
  const IN = (d = .9, off = 0) => clamp((t - S.a - off) / d);          // shot-local ramp from the shot start
  return { G, U, IN };
}
// runner x on a straight: from x0 at t0 to x1 at t1 (sine eased) — used for camera-free races
export const runX = (t, t0, t1, x0, x1, e = sineIO) => lerp(x0, x1, e(span(t, t0, t1)));

// ---------------------------------------------------------------------------------------------------------------- shared shot types
// an ORIGINAL FOOTAGE plate that grows out of S.in and shrinks back into it when the clip ends
export function clipShot(id) {
  return (ctx, t, S, T) => {
    const c = T.clip(id);
    bg(ctx, t, { gx: S.in[0], gy: S.in[1], ga: .2, stars: 40 });
    const m = sineIO(span(t, S.a, S.a + .6)) * (1 - sineIO(span(t, c.end - .05, c.end + .45)));
    if (m <= 0) return;
    K.clipPlate(ctx, t, T, id, { from: [S.in[0], S.in[1], 14], morph: m });
  };
}
export const ROUNDS = [['ROUND 1 · THE MACHINES', 'US'], ['ROUND 2 · THE CHIPS', 'US'], ['ROUND 3 · POWER', 'CN'], ['ROUND 4 · BUILDERS AND BODIES', 'CN']];
// the scorecard after round k (0-based): rows 0..k-1 already won, row k's dot flies on the phrase 'Point'
export function pointShot(k, phrase = 'Point') {
  return (ctx, t, S, T) => {
    const { U, IN } = phr(T, S, t);
    bg(ctx, t, { gx: 960, gy: 300, ga: .28 });
    ctx.save(); shotCam(ctx, t, S, { z0: 1.03, z1: 1, fy: 300 });
    const wu = U(phrase, .7, .05);
    const rows = ROUNDS.slice(0, k + 1).map(([label, win], i) => ({ label, win, u: i < k ? 1 : IN(.6), wu: i < k ? 1 : wu, hi: i === k }));
    const us = rows.filter((r) => r.win === 'US' && r.wu > .9).length, cn = rows.filter((r) => r.win === 'CN' && r.wu > .9).length;
    const win = ROUNDS[k][1], fl = span(wu, .85, 1) * (1 - span(t, S.t0 + 1.6, S.t0 + 2.6));
    scorecard(ctx, t, { y: 160, u: IN(.7), us, cn, rows, flash: fl > 0 ? { side: win, a: fl } : null });
    cap(ctx, `POINT: ${win === 'US' ? 'AMERICA' : 'CHINA'}`, 960, 900, U(phrase, .7, .1), { size: 44, align: 'center', col: win === 'US' ? US.text : CN.text, glow: true });
    ctx.restore();
  };
}
// the round title: ROUND n · NAME + four round dots (n lit)
export function roundTitle(ctx, t, k, u, y = 140) {
  if (u <= 0) return;
  cap(ctx, ROUNDS[k][0], 960, y, u, { size: 40, align: 'center', col: GOLD.text, glow: true });
  for (let i = 0; i < 4; i++) { ctx.save(); ctx.globalAlpha *= u; ctx.fillStyle = i === k ? GOLD.hot : rgba(MUTED, .45); ctx.beginPath(); ctx.arc(960 - 60 + i * 40, y + 40, i === k ? 9 : 6, 0, TAU); ctx.fill(); ctx.restore(); }
}
// a pill tag with text (outline), centred at x
export function tag(ctx, s, x, y, u, o = {}) {
  if (u <= 0) return; const size = o.size ?? 24, w = K.measure(s, size, false, 600) + size * s.length * .02 + 56, k = expoOut(clamp(u));
  ctx.save(); ctx.globalAlpha *= clamp(u * 3); if (o.dash) ctx.setLineDash([10, 8]); ctx.strokeStyle = rgba(o.col ?? CREAM, .85); ctx.lineWidth = 2;
  if (o.fill) { ctx.fillStyle = rgba(o.fill, .18); ctx.beginPath(); ctx.roundRect(x - w / 2 * k, y - size * 1.2, w * k, size * 2.2, size * 1.1); ctx.fill(); }
  ctx.beginPath(); ctx.roundRect(x - w / 2 * k, y - size * 1.2, w * k, size * 2.2, size * 1.1); ctx.stroke(); ctx.restore();
  cap(ctx, s, x, y + size * .36, u, { size, align: 'center', col: o.col ?? CREAM });
}
